// Supabase Edge Function (Deno runtime) — creates student login accounts
// directly, with a username and password chosen/generated by school staff,
// instead of the email-invite flow. Built for younger students who don't
// have a checkable email address.
//
// This is the ONLY place a student account can be created with
// app_metadata.staff_created_student_org set — the handle_new_user trigger
// (migration 0087) only trusts that field, and app_metadata can only be set
// through the Admin API (this function, via the service-role key), never
// through the public /auth/v1/signup endpoint. That's what keeps this from
// being an open door for anyone to self-register as a student.

import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

function json(body: unknown, status = 200, origin: string | null = null, allowedOrigins: string[] = []) {
  const headers: Record<string, string> = {
    "Content-Type": "application/json",
    Vary: "Origin",
  };
  if (origin && allowedOrigins.includes(origin)) {
    headers["Access-Control-Allow-Origin"] = origin;
    headers["Access-Control-Allow-Headers"] = "authorization, x-client-info, apikey, content-type";
    headers["Access-Control-Allow-Methods"] = "POST, OPTIONS";
  }
  return new Response(JSON.stringify(body), { status, headers });
}

async function trySupabase<T>(request: PromiseLike<T>): Promise<T | null> {
  try {
    return await request;
  } catch {
    return null;
  }
}

interface StudentRequest {
  fullName: string;
  username: string;
}

const USERNAME_RE = /^[a-z0-9._-]{3,32}$/;
const MAX_BATCH = 100;

function randomPassword() {
  // Memorable-ish but not guessable: two short words + a 3-digit number.
  const words = ["race", "track", "pit", "turbo", "drift", "lap", "grid", "nitro", "spark", "dash"];
  const w1 = words[Math.floor(Math.random() * words.length)];
  const w2 = words[Math.floor(Math.random() * words.length)];
  const n = Math.floor(100 + Math.random() * 900);
  return `${w1}${w2}${n}`;
}

Deno.serve(async (req) => {
  const origin = req.headers.get("Origin");
  const allowedOrigins = (Deno.env.get("ALLOWED_ORIGINS") ?? "")
    .split(",")
    .map((value) => value.trim().replace(/\/$/, ""))
    .filter(Boolean);
  const normalizedOrigin = origin?.replace(/\/$/, "") ?? null;
  const respond = (body: unknown, status = 200) => json(body, status, normalizedOrigin, allowedOrigins);

  if (allowedOrigins.length === 0) {
    return respond({ error: "This feature isn't configured yet." }, 500);
  }
  if (normalizedOrigin && !allowedOrigins.includes(normalizedOrigin)) {
    return respond({ error: "This origin is not allowed." }, 403);
  }
  if (req.method === "OPTIONS") {
    const headers = new Headers({ Vary: "Origin" });
    if (normalizedOrigin) {
      headers.set("Access-Control-Allow-Origin", normalizedOrigin);
      headers.set("Access-Control-Allow-Headers", "authorization, x-client-info, apikey, content-type");
      headers.set("Access-Control-Allow-Methods", "POST, OPTIONS");
    }
    return new Response("ok", { headers });
  }
  if (req.method !== "POST") {
    return respond({ error: "Method not allowed." }, 405);
  }

  const supabaseUrl = Deno.env.get("SUPABASE_URL");
  const anonKey = Deno.env.get("SUPABASE_ANON_KEY");
  const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
  if (!supabaseUrl || !anonKey || !serviceRoleKey) {
    return respond({ error: "This feature isn't configured yet." }, 500);
  }

  // 1. Authenticate the caller using their forwarded JWT.
  const authClient = createClient(supabaseUrl, anonKey, {
    global: { headers: { Authorization: req.headers.get("Authorization") ?? "" } },
  });
  const authResult = await trySupabase(authClient.auth.getUser());
  if (!authResult) {
    return respond({ error: "Authentication is temporarily unavailable. Please try again." }, 503);
  }
  const { data: { user }, error: authError } = authResult;
  if (authError || !user) {
    return respond({ error: "You must be signed in to do this." }, 401);
  }

  let body: { orgId?: string; students?: StudentRequest[] };
  try {
    body = await req.json();
  } catch {
    return respond({ error: "Invalid request body." }, 400);
  }

  const orgId = typeof body.orgId === "string" ? body.orgId : "";
  if (!orgId) return respond({ error: "A school is required." }, 400);

  // 2. Authorize: reuse the same server-side rule invite_students() uses,
  // via the caller's own JWT (so RLS/can_manage_org applies exactly as it
  // does everywhere else — this function has no special authority of its
  // own beyond what the caller is already allowed to do).
  const canManageResult = await trySupabase(authClient.rpc("can_manage_org", { p_org: orgId }));
  if (!canManageResult) {
    return respond({ error: "Authorization check is temporarily unavailable. Please try again." }, 503);
  }
  const { data: canManage, error: canManageError } = canManageResult;
  if (canManageError || !canManage) {
    return respond({ error: "You cannot create student accounts for this school." }, 403);
  }

  const students = Array.isArray(body.students) ? body.students.slice(0, MAX_BATCH) : [];
  if (students.length === 0) {
    return respond({ error: "Add at least one student." }, 400);
  }

  const adminClient = createClient(supabaseUrl, serviceRoleKey);
  const seen = new Set<string>();
  const results: { username: string; fullName: string; password?: string; result: string }[] = [];

  for (const student of students) {
    const fullName = typeof student.fullName === "string" ? student.fullName.trim() : "";
    const username = typeof student.username === "string" ? student.username.trim().toLowerCase() : "";

    if (!fullName) {
      results.push({ username, fullName, result: "missing_name" });
      continue;
    }
    if (!USERNAME_RE.test(username)) {
      results.push({ username, fullName, result: "invalid_username" });
      continue;
    }
    if (seen.has(username)) {
      results.push({ username, fullName, result: "duplicate_in_list" });
      continue;
    }
    seen.add(username);

    const existingResult = await trySupabase(
      adminClient.from("profiles").select("id").ilike("username", username).maybeSingle(),
    );
    if (existingResult?.data) {
      results.push({ username, fullName, result: "username_taken" });
      continue;
    }

    const password = randomPassword();
    const placeholderEmail = `${username}.${crypto.randomUUID().slice(0, 8)}@students.hanbee.internal`;

    const createResult = await trySupabase(
      adminClient.auth.admin.createUser({
        email: placeholderEmail,
        password,
        email_confirm: true,
        user_metadata: { full_name: fullName },
        app_metadata: { staff_created_student_org: orgId, student_username: username },
      }),
    );
    if (!createResult || createResult.error) {
      results.push({ username, fullName, result: "failed" });
      continue;
    }

    results.push({ username, fullName, password, result: "created" });
  }

  return respond({ results });
});
